const menu = [
 {id:'chicken',name:'Chicken',kind:'Biryani',price:299,category:'signature',tag:'Comfort classic',heat:'Medium spice',description:'Tender chicken, fragrant basmati and caramelised onions, layered with our signature spice blend.',image:'chicken'},
 {id:'mutton',name:'Mutton',kind:'Biryani',price:399,category:'signature',tag:'The signature',heat:'Medium spice',description:'Slow-cooked mutton and saffron-kissed rice. Rich, aromatic, and worth taking your time over.',image:'biryani'},
 {id:'fish',name:'Fish',kind:'Biryani',price:349,category:'signature',tag:'Coastal favourite',heat:'Warm spice',description:'Spiced fish nestled in long-grain rice with herbs, a squeeze of lemon and a little coastal soul.',image:'fish'},
 {id:'vegetable',name:'Garden veg',kind:'Biryani',price:229,category:'vegetarian',tag:'Vegetarian',heat:'Mild spice',description:'Seasonal vegetables, mint and golden basmati, finished with crispy onions. Colour in every spoonful.',image:'vegetable'},
 {id:'paneer',name:'Paneer',kind:'Biryani',price:279,category:'vegetarian',tag:'Vegetarian',heat:'Medium spice',description:'Golden paneer, aromatic rice and warming whole spices. A comforting vegetarian favourite.',image:'paneer'},
 {id:'raita',name:'Cucumber raita',kind:'On the side',price:59,category:'sides',tag:'Vegetarian',heat:'Cool & fresh',description:'Creamy yoghurt with crisp cucumber, fresh mint and roasted cumin. A little calm for your spice.',image:'raita'}
];
const money=n=>'₹'+n; let cart={}; try{const saved=JSON.parse(localStorage.getItem('dum-spice-order')||'{}');menu.forEach(item=>{if(Number.isInteger(saved[item.id])&&saved[item.id]>0&&saved[item.id]<=99)cart[item.id]=saved[item.id]})}catch{}
const track=document.querySelector('#menuTrack'),dialog=document.querySelector('#orderDialog');let toastTimer;
function renderMenu(filter='all'){track.innerHTML=menu.filter(item=>filter==='all'||item.category===filter).map(item=>`<article class="dish" data-id="${item.id}"><div class="dish-image"><div class="dish-photo photo-${item.image}" role="img" aria-label="${item.name} ${item.kind}"></div><div class="dish-price"><small>PRICE</small><strong>${money(item.price)}</strong></div></div><div class="dish-body"><span class="dish-kicker">${item.kind}</span><h3>${item.name}</h3><p>${item.description}</p><div class="dish-meta"><span>${item.tag}</span><span>${item.heat}</span></div><button class="dish-add" data-add="${item.id}" aria-label="Add ${item.name} to order">ADD TO ORDER &nbsp; +</button></div></article>`).join('');track.scrollLeft=0}
function updateCart(){try{localStorage.setItem('dum-spice-order',JSON.stringify(cart))}catch{}document.querySelector('#bagCount').textContent=Object.values(cart).reduce((a,b)=>a+b,0);const chosen=menu.filter(i=>cart[i.id]);document.querySelector('#orderItems').innerHTML=chosen.length?chosen.map(i=>`<div class="order-row"><div><strong>${i.name}${i.kind==='Biryani'?' biryani':''}</strong><small>${money(i.price)} each</small></div><div class="quantity"><button data-change="${i.id}" data-delta="-1" aria-label="Remove one ${i.name}">−</button><span>${cart[i.id]}</span><button data-change="${i.id}" data-delta="1" aria-label="Add one ${i.name}">+</button></div><strong>${money(i.price*cart[i.id])}</strong></div>`).join(''):'<p class="empty">Your next favourite is waiting.<br>Choose something delicious from the menu.</p>';document.querySelector('#subtotal').textContent=money(chosen.reduce((sum,i)=>sum+i.price*cart[i.id],0));document.querySelector('#copyOrder').disabled=!chosen.length;document.querySelector('#clearOrder').hidden=!chosen.length;document.querySelector('#copyStatus').textContent=''}
function notify(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2300)}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){const id=add.dataset.add;cart[id]=Math.min(99,(cart[id]||0)+1);updateCart();notify(menu.find(i=>i.id===id).name+' added to your order')}const change=e.target.closest('[data-change]');if(change){const id=change.dataset.change;cart[id]=Math.min(99,(cart[id]||0)+Number(change.dataset.delta));if(cart[id]<=0)delete cart[id];updateCart()}});
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn))});renderMenu(btn.dataset.filter)}));
document.querySelector('#prev').onclick=()=>track.scrollBy({left:-track.clientWidth*.8,behavior:'smooth'});document.querySelector('#next').onclick=()=>track.scrollBy({left:track.clientWidth*.8,behavior:'smooth'});
document.querySelector('#openBag').onclick=()=>{updateCart();dialog.showModal()};document.querySelector('#closeBag').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});document.querySelector('#clearOrder').onclick=()=>{cart={};updateCart()};
document.querySelector('#copyOrder').onclick=async()=>{const items=menu.filter(i=>cart[i.id]);const summary='DUM & SPICE — ORDER SUMMARY\n\n'+items.map(i=>`${cart[i.id]} × ${i.name} ${i.kind==='Biryani'?'biryani':''} — ${money(cart[i.id]*i.price)}`).join('\n')+'\n\nSubtotal: '+money(items.reduce((sum,i)=>sum+cart[i.id]*i.price,0))+'\nSample menu. Confirm availability and final price with the restaurant.';try{await navigator.clipboard.writeText(summary);document.querySelector('#copyStatus').textContent='Copied! Share your summary with the restaurant to confirm your order.'}catch{const area=document.createElement('textarea');area.value=summary;area.setAttribute('aria-label','Order summary — select and copy');area.style.cssText='width:100%;min-height:180px;margin-top:20px';document.querySelector('#copyStatus').replaceChildren(area);area.select()}};
renderMenu();updateCart();
